 <html lang="en">
 <head>
   <meta charset="UTF-8">
   <meta name="viewport" content="width=device-width, initial-scale=1.0">
   <title>Terms Consent</title>
   <style>
     :root {
       color-scheme: light;
       --bg: #f4f7fb;
       --surface: #ffffff;
       --text: #1f2937;
       --muted: #5b6472;
       --border: #d8e0ea;
       --accent: #2457ff;
       --accent-strong: #1d46cc;
       --error: #b42318;
       --shadow: 0 18px 50px rgba(15, 23, 42, 0.12);
       --radius: 20px;
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font: 16px/1.5 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       color: var(--text);
       background:
         radial-gradient(circle at top, rgba(36, 87, 255, 0.12), transparent 35%),
         linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
       display: grid;
       place-items: center;
       padding: 24px;
     }

     main {
       width: min(100%, 460px);
     }

     .card {
       background: var(--surface);
       border: 1px solid rgba(216, 224, 234, 0.9);
       border-radius: var(--radius);
       box-shadow: var(--shadow);
       padding: 32px;
     }

     h1 {
       margin: 0 0 8px;
       font-size: clamp(1.5rem, 3vw, 2rem);
       line-height: 1.2;
       letter-spacing: -0.02em;
     }

     .subtitle {
       margin: 0 0 24px;
       color: var(--muted);
     }

     form {
       display: grid;
       gap: 20px;
     }

     .form-field {
       padding: 18px;
       border: 1px solid var(--border);
       border-radius: 16px;
       background: #fbfdff;
     }

     .checkbox-row {
       display: flex;
       gap: 12px;
       align-items: flex-start;
     }

     input[type="checkbox"] {
       width: 20px;
       height: 20px;
       margin: 2px 0 0;
       accent-color: var(--accent);
       flex: 0 0 auto;
     }

     label {
       display: block;
       font-weight: 600;
       cursor: pointer;
     }

     .required-mark {
       color: var(--accent-strong);
     }

     .help-text,
     .error-text {
       margin: 6px 0 0;
       font-size: 0.9375rem;
     }

     .help-text {
       color: var(--muted);
     }

     .error-text {
       color: var(--error);
     }

     .form-field[data-invalid="true"] {
       border-color: rgba(180, 35, 24, 0.35);
       background: #fff8f7;
     }

     .form-actions {
       display: flex;
       justify-content: flex-end;
     }

     button {
       appearance: none;
       border: 0;
       border-radius: 999px;
       padding: 0.9rem 1.3rem;
       font: inherit;
       font-weight: 700;
       color: white;
       background: linear-gradient(180deg, var(--accent) 0%, var(--accent-strong) 100%);
       box-shadow: 0 10px 24px rgba(36, 87, 255, 0.22);
       cursor: pointer;
     }

     button:hover {
       filter: brightness(1.03);
     }

     button:focus-visible,
     input:focus-visible {
       outline: 3px solid #111827;
       outline-offset: 3px;
     }

     [hidden] {
       display: none !important;
     }

     .status {
       min-height: 1.5em;
       margin: 0;
       color: var(--accent-strong);
       font-weight: 600;
     }
   </style>
 </head>
 <body>
   <main>
     <section class="card" aria-labelledby="consent-title">
       <h1 id="consent-title">Agree to continue</h1>
       <p class="subtitle">Review the terms before submitting.</p>

       <form id="consent-form" novalidate>
         <div class="form-field" data-invalid="false">
           <div class="checkbox-row">
             <input
               id="agree-terms"
               name="agree-terms"
               type="checkbox"
               required
               aria-describedby="agree-help agree-error"
             >
             <div>
               <label for="agree-terms">
                 I agree to the terms of use <span class="required-mark" aria-hidden="true">*</span>
               </label>
               <p id="agree-help" class="help-text">Required to finish sign-up.</p>
               <p id="agree-error" class="error-text" hidden>Error: Please agree to the terms to continue.</p>
             </div>
           </div>
         </div>

         <div class="form-actions">
           <button type="submit">Continue</button>
         </div>

         <p id="status" class="status" aria-live="polite"></p>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById('consent-form');
     const checkbox = document.getElementById('agree-terms');
     const field = checkbox.closest('.form-field');
     const error = document.getElementById('agree-error');
     const status = document.getElementById('status');

     function setErrorState(isInvalid) {
       field.dataset.invalid = String(isInvalid);
       checkbox.setAttribute('aria-invalid', String(isInvalid));
       error.hidden = !isInvalid;
     }

     form.addEventListener('submit', (event) => {
       if (!checkbox.checked) {
         event.preventDefault();
         setErrorState(true);
         status.textContent = '';
         checkbox.focus();
         return;
       }

       event.preventDefault();
       setErrorState(false);
       status.textContent = 'Terms accepted.';
     });

     checkbox.addEventListener('change', () => {
       if (checkbox.checked) {
         setErrorState(false);
       }
     });
   </script>
 </body>
 </html>

