       gap: 20px;
     }

     .form-field {
       padding: 18px;
       border: 1px solid var(--border);
       border-radius: 16px;
       background: #fbfdff;
     }

     .checkbox-row {
       display: flex;
       gap: 12px;
       align-items: flex-start;
     }

     input[type="checkbox"] {
       width: 20px;
       height: 20px;
       margin: 2px 0 0;
       accent-color: var(--accent);
       flex: 0 0 auto;
     }

     label {
       display: block;
       font-weight: 600;
       cursor: pointer;
     }

     .required-mark {
       color: var(--accent-strong);
