       color: var(--muted);
     }

     .error-text {
       color: var(--error);
     }

     .form-field[data-invalid="true"] {
       border-color: rgba(180, 35, 24, 0.35);
       background: #fff8f7;
     }

     .form-actions {
       display: flex;
       justify-content: flex-end;
     }

